// Cooperative yield: returns a promise resolved on next animation frame
// (or microtask in non-DOM environments like Deno tests).
const _yieldFrame = () => {
  if (typeof requestAnimationFrame === 'function') {
    return new Promise((r) => requestAnimationFrame(() => r()));
  }
  return Promise.resolve();
};

/**
 * Generate all chunks for a floor and materialize everything at once.
 * Returns entity IDs created for bulk cleanup on transition.
 *
 * Async: when `onProgress` is provided, yields to the browser between chunks
 * so the loading UI can repaint. Without `onProgress` the function still
 * returns a Promise (for API consistency) but does no yields.
 *
 * @param {import('../../../lib/ecs-js/index.js').World} world
 * @param {number} worldSeed
 * @param {number} depth
 * @param {Object} [tombstoneRepo] - Tombstone repository for placing tombstones
 * @param {(progress: { phase: 'chunks', depth: number, processed: number, total: number, cx?: number, cy?: number }) => void} [onProgress]
 * @param {{x:number,y:number}[]|null} [priorDownStairPositions]
 *   Actual world positions of down-stairs on the floor above; passed to
 *   generateFloorPlan so up-stairs inherit those exact positions.
 * @returns {Promise<{ spawnX: number, spawnY: number, entityIds: number[], downStairPositions: {x:number,y:number}[], profileType: string }>}
 */
export async function generateFloor(world, worldSeed, depth, tombstoneRepo = null, onProgress = null, priorDownStairPositions = null, opts = {}) {
  const _yield = onProgress ? _yieldFrame : null;
  const highscoreProvider = typeof opts.getHighscores === 'function' ? opts.getHighscores : null;
  // Yield every N chunks to keep UI responsive without slowing gen too much.
  const _YIELD_EVERY = 2;
  if (depth === 0) {
    const ow = await generateOverworldChunks(worldSeed, onProgress);

    // Church graveyard epitaph source priority:
    // 1) Pin top 5 global highscores in rank order to the five church graves.
    // 2) If globals are shallow/missing, top up remaining graves from local tombstones.
    if (tombstoneRepo) {
      const graveSpawns = [];
      for (const chunkData of ow.chunks) {
        const chunkSpawns = Array.isArray(chunkData?.spawns) ? chunkData.spawns : [];
        for (const spawn of chunkSpawns) {
          if (spawn?.kind === 'grave_tombstone') graveSpawns.push(spawn);
        }
      }

      if (graveSpawns.length > 0) {
        // Deterministic slot order: south row left→right, then north row left→right.
        graveSpawns.sort((a, b) => {
          const ay = Number(a?.y || 0) | 0;
          const by = Number(b?.y || 0) | 0;
          if (ay !== by) return by - ay;
          const ax = Number(a?.x || 0) | 0;
          const bx = Number(b?.x || 0) | 0;
          return ax - bx;
        });

        const graveRng = createRng(((worldSeed >>> 0) ^ 0x47524156) >>> 0);
        const records = [];

        const highscores = highscoreProvider ? highscoreProvider() : null;
        const maxGlobalPinned = Math.min(5, graveSpawns.length);
        if (Array.isArray(highscores) && highscores.length > 0) {
          const top = highscores.slice(0, maxGlobalPinned);
          for (let i = 0; i < top.length; i++) {
            const entry = top[i];
            records.push({
              id: `church_global_rank_${i + 1}`,
              depth: 0,
              cause: 'highscore',
              killerName: null,
              killerIdentity: null,
              timestamp: 0,
              turn: 0,
              playerName: String(entry?.playerName || 'Hero'),
              className: String(entry?.className || ''),
              score: Math.max(0, Number(entry?.score || 0) | 0),
              rank: i + 1,
            });
          }
        }

        if (records.length < graveSpawns.length) {
          const fallbackPool = Array.isArray(tombstoneRepo.getAll?.()) ? tombstoneRepo.getAll() : [];
          const shuffled = [...fallbackPool];
          for (let i = shuffled.length - 1; i > 0; i--) {
            const j = Math.floor(graveRng.next() * (i + 1));
            [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
          }
          for (const rec of shuffled) {
            if (records.length >= graveSpawns.length) break;
            const duplicate = records.some((r) => String(r?.id || '') === String(rec?.id || ''));
            if (!duplicate) records.push(rec);
          }
        }

        for (let i = 0; i < graveSpawns.length; i++) {
          const data = records[i] || null;
          const spawn = graveSpawns[i];
          spawn.params = { ...(spawn.params || {}) };
          if (data) spawn.params.tombstoneData = data;
        }
      }
    }

    const totalChunks = ow.chunks.length;
    let processedChunks = 0;

    if (typeof onProgress === 'function') {
      onProgress({ phase: 'chunks', depth, processed: 0, total: totalChunks });
    }

    const entranceByPos = new Map();
    const buildings = Array.isArray(ow?.townPlan?.buildings) ? ow.townPlan.buildings : [];
    const tavern = buildings.find((b) => b?.key === "tavern");
    const graveyard = buildings.find((b) => b?.key === "graveyard");
    const addEntrance = (pos, templateId) => {
      if (!pos) return;
      const template = getUnderworldRegionTemplate(templateId);
      if (!template) return;
      entranceByPos.set(`${pos.x | 0},${pos.y | 0}`, {
        templateId: template.templateId,
        label: template.label,
        type: template.type,
        floors: template.floors,
        biome: template.biome,
        monsterTier: template.monsterTier,
        lootTier: template.lootTier,
        questId: template.questId,
        lockId: String(template.lockId || ""),
        lockDifficulty: String(template.lockDifficulty || ""),
        targetDepth: template.targetDepth,
        anchorX: pos.x | 0,
        anchorY: pos.y | 0,
      });
    };
    addEntrance(tavern?.waypoints?.cellar_stairs, "tavern_basement");
    addEntrance(graveyard?.waypoints?.crypt_entrance, "graveyard_crypt");
    for (const chunkData of ow.chunks) {
      const chunkSpawns = Array.isArray(chunkData?.spawns) ? chunkData.spawns : [];
      for (const spawn of chunkSpawns) {
        const templateId = String(spawn?.params?.entranceTemplateId || "");
        if (!templateId) continue;
        addEntrance({ x: spawn.x | 0, y: spawn.y | 0 }, templateId);
      }
    }

    const stairOpts = {
      createStairDown: (w, x, y) => {
        const id = createFrom(w, StairDown, { x, y });
        const entrance = entranceByPos.get(`${x | 0},${y | 0}`);
        if (entrance) w.add(id, DungeonEntrance, entrance);
        return id;
      },
      createStairUp: (w, x, y) => createFrom(w, StairUp, { x, y }),
    };

    const allEntityIds = [];
    for (const chunkData of ow.chunks) {
      tileMapLoad(chunkData.chunkX, chunkData.chunkY, chunkData.tiles);
      loadRoofedChunk(chunkData.chunkX, chunkData.chunkY, chunkData.roofed);
      const ids = materializeChunk(world, chunkData, stairOpts);
      allEntityIds.push(...ids);
      processedChunks++;
      if (typeof onProgress === 'function') {
        onProgress({
          phase: 'chunks',
          depth,
          processed: processedChunks,
          total: totalChunks,
          cx: chunkData.chunkX,
          cy: chunkData.chunkY,
        });
      }
      if (_yield && (processedChunks % _YIELD_EVERY) === 0) await _yield();
    }

    reconcileShopDoorAccess(world);

