 * @returns {boolean} true if no overlap
 */
export function canPlaceBuilding(chunks, anchorX, anchorY, buildingDef, isOccupied) {
  for (const { dx, dy } of buildingDef.tiles) {
    const wx = anchorX + dx;
    const wy = anchorY + dy;
    if (isOccupied(wx, wy)) return false;
  }
  return true;
}
